PARAMETER DESCRIPTION <code>deep</code> <p>Should we resolve deeply</p> <p> DEFAULT: <code>True</code> </p> <code>registry</code> <p>Registry to use when resolving</p> <p> TYPE: <code>Any</code> DEFAULT: <code>None</code> </p> <code>root</code> <p>The root of the config tree. Used for resolving references.</p> <p> TYPE: <code>Mapping</code> DEFAULT: <code>None</code> </p> RETURNS DESCRIPTION <code>Union[Config, Any]</code> Source code in <code>confit/config.py</code> <pre><code>def resolve(self, deep=True, registry: Any = None, root: Mapping = None) -&gt; Any:
"""
    Resolves the parts of the nested config object with @ variables using
    a registry, and then interpolate references in the config.

    Parameters
    ----------
    deep: bool
        Should we resolve deeply
    registry:
        Registry to use when resolving
    root: Mapping
        The root of the config tree. Used for resolving references.

    Returns
    -------
    Union[Config, Any]
    """
    if root is None:
        root = self

    if registry is None:
        from .registry import get_default_registry

        registry = get_default_registry()
    resolved_locs = {}
    seen_locs = set()

    def resolve_reference(ref: Reference) -&gt; Any:
        pat = re.compile(PATH + ":?")

        def replace(match: re.Match):
            start = match.start()
            if start &gt; 0 and ref.value[start - 1] == ":":
                return match.group()

            path = match.group()
            parts = split_path(path.rstrip(":"))

            # Check if part is any special python keyword
            if len(parts) == 1 and parts[0] in keyword.kwlist:
                return match.group()
            try:
                return local_names[parts] + ("." if path.endswith(":") else "")
            except KeyError:
                raise KeyError(path)

        local_names = {}
        for match in pat.finditer(ref.value):
            start = match.start()
            if start &gt; 0 and ref.value[start - 1] == ":":
                continue
            path = match.group()
            parts = split_path(path.rstrip(":"))
            if len(parts) == 1 and parts[0] in keyword.kwlist:
                continue
            local_names.setdefault(parts, f"var_{len(local_names)}")

        local_leaves = DynamicLocals(local_names, root, resolved_locs, rec)

        replaced = pat.sub(replace, ref.value)

        res = safe_eval(replaced, local_leaves)

        return res

    def rec(obj, loc: Tuple[Union[str, int]] = ()):
"""
        Parameters
        ----------
        obj: Any
            The current object being resolved
        loc: Sequence[str]
            Internal variable
            Current path in tree

        Returns
        -------

        """
        if id(obj) in resolved_locs:
            return resolved_locs[id(obj)]

        if id(obj) in seen_locs:
            raise CyclicReferenceError(tuple(loc))

        seen_locs.add(id(obj))

        if not deep and len(loc) &gt; 1:
            return obj

        if isinstance(obj, Mapping):
            resolved = Config({k: rec(v, (*loc, k)) for k, v in obj.items()})

            registries = [
                (key, value, getattr(registry, key[1:]))
                for key, value in resolved.items()
                if isinstance(key, str) and key.startswith("@")
            ]
            assert len(registries) &lt;= 1, (
                f"Cannot resolve using multiple registries at {'.'.join(loc)}"
            )

            if len(registries) == 1:
                raw_key, value, registry_value = registries[0]
                cfg = resolved
                params = dict(resolved)
                params.pop(raw_key)
                value = value.strip()
                is_draft = value.endswith("!draft")
                if is_draft:
                    value = value[: -len("!draft")].strip()
                fn = registry_value.get(value)
                try:
                    if is_draft:
                        resolved = Draft(fn, params, loc)
                    else:
                        resolved = fn(**params)
                    # The `validate_arguments` decorator has most likely
                    # already put the resolved config in the registry
                    # but for components that are instantiated without it
                    # we need to do it here
                    Config._store_resolved(resolved, cfg)
                except ConfitValidationError as e:
                    e = e.with_path(loc).with_traceback(
                        remove_lib_from_traceback(e.__traceback__)
                    )
                    if not is_debug():
                        e.__cause__ = None
                        e.__suppress_context__ = True
                    raise e

        elif isinstance(obj, list):
            resolved = [rec(v, (*loc, i)) for i, v in enumerate(obj)]
        elif isinstance(obj, tuple):
            resolved = tuple(rec(v, (*loc, i)) for i, v in enumerate(obj))
        elif isinstance(obj, Reference):
            while True:
                try:
                    resolved = resolve_reference(obj)
                    break
                except (KeyError, NameError):
                    raise MissingReference(obj)
        else:
            resolved = obj

        resolved_locs[id(obj)] = resolved

        return resolved

    return rec(self, ())
