PARAMETER DESCRIPTION <code>updates</code> <p>Configs to update the original config</p> <p> TYPE: <code>Union[Dict[str, Any], Config]</code> DEFAULT: <code>()</code> </p> <code>remove_extra</code> <p>If true, restricts update to keys that existed in the original config</p> <p> TYPE: <code>bool</code> DEFAULT: <code>False</code> </p> RETURNS DESCRIPTION <code>The new config</code> Source code in <code>confit/config.py</code> <pre><code>def merge(
    self,
    *updates: Union[Dict[str, Any], "Config"],
    remove_extra: bool = False,
) -&gt; "Config":
"""
    Deep merge two configs. Heavily inspired from `thinc`'s config merge function.

    Parameters
    ----------
    updates: Union[Config, Dict]
        Configs to update the original config
    remove_extra:
        If true, restricts update to keys that existed in the original config

    Returns
    -------
    The new config
    """

    def deep_set(current, path, val):
        if path not in current and remove_extra:
            return
        current[path] = val

    def rec(old, new):
        for key, new_val in list(new.items()):
            if "." in key:
                deep_set(old, key, new_val)
                continue

            if key not in old:
                if remove_extra:
                    continue
                else:
                    old[key] = new_val
                    continue

            old_val = old[key]
            if isinstance(old_val, dict) and isinstance(new_val, dict):
                old_resolver = next(
                    (
                        k
                        for k in old_val
                        if isinstance(key, str) and k.startswith("@")
                    ),
                    None,
                )
                new_resolver = next(
                    (
                        k
                        for k in new_val
                        if isinstance(key, str) and k.startswith("@")
                    ),
                    None,
                )
                if (
                    new_resolver is not None
                    and old_resolver is not None
                    and (
                        old_resolver != new_resolver
                        or old_val.get(old_resolver) != new_val.get(new_resolver)
                    )
                ):
                    old[key] = new_val
                else:
                    rec(old[key], new_val)
            else:
                old[key] = new_val
        return old

    config = self.copy()
    for u in updates:
        rec(config, u)
    return config
